    "source": "import java.util.ArrayList;\nimport java.util.Arrays;\nimport java.util.List;\n\n/** N-Queens backtracking — complete Java reference. */\npublic final class NQueens {\n    private final int n;\n    private final int[] cols;\n    private final List<int[]> solutions = new ArrayList<>();\n\n    private NQueens(int n) {\n        this.n = n;\n        this.cols = new int[n];\n        Arrays.fill(cols, -1);\n    }\n\n    public static List<int[]> solveNQueens(int n) {\n        NQueens s = new NQueens(n);\n        s.dfs(0);\n        return s.solutions;\n    }\n\n    private boolean isSafe(int row, int col) {\n        for (int r = 0; r < row; r++) {\n            int c = cols[r];\n            if (c == col || Math.abs(c - col) == row - r) return false;\n        }\n        return true;\n    }\n\n    private void dfs(int row) {\n        if (row == n) {\n            solutions.add(cols.clone());\n            return;\n        }\n        for (int col = 0; col < n; col++) {\n            if (!isSafe(row, col)) continue;\n            cols[row] = col;\n            dfs(row + 1);\n            cols[row] = -1;\n        }\n    }\n}\n",
