    "source": "/// N-Queens backtracking — complete Rust reference.\npub fn solve_n_queens(n: usize) -> Vec<Vec<i32>> {\n    fn is_safe(cols: &[i32], row: usize, col: i32) -> bool {\n        for r in 0..row {\n            let c = cols[r];\n            if c == col || (c - col).abs() == (row - r) as i32 {\n                return false;\n            }\n        }\n        true\n    }\n    fn dfs(row: usize, n: usize, cols: &mut Vec<i32>, solutions: &mut Vec<Vec<i32>>) {\n        if row == n {\n            solutions.push(cols.clone());\n            return;\n        }\n        for col in 0..n as i32 {\n            if !is_safe(cols, row, col) {\n                continue;\n            }\n            cols[row] = col;\n            dfs(row + 1, n, cols, solutions);\n            cols[row] = -1;\n        }\n    }\n    let mut solutions: Vec<Vec<i32>> = Vec::new();\n    let mut cols = vec![-1; n];\n    dfs(0, n, &mut cols, &mut solutions);\n    solutions\n}\n",
